local p = setmetatable({}, {__index=function(t,k) if k<3 then return k*10 end end})
local it = ipairs(p)
print(pcall(it, p, 0))
print(xpcall(it, print, p, 0))
print(pcall(it, p, 2))
print(pcall(function() return setmetatable({}, {__index = it})[0] end))
local q = setmetatable({}, {__index=function(t,k) if k<3 then return k*10 end end})
local mt = setmetatable({}, {__index = it})
print(pcall(function() return mt[0] end))
print(select('#', pcall(it, p, 5)), pcall(it, p, 5))
local co = coroutine.wrap(function() return pcall(it, setmetatable({}, {__index=function(t,k) return coroutine.yield(k) end}), 0) end)
print(pcall(co))
local p4 = setmetatable({}, {__index=function(t,k) return k end})
print(pcall(it, p4, "x"))
print(pcall(it, p4))
print(pcall(it, p4, 1.5))
print(pcall(it, p4, 2.0))
print(pcall(function() return setmetatable({}, {__index = it}).x end))
